WITH k(ts) AS (SELECT CAST(v AS datetime) FROM (VALUES ('2026-07-07 10:13:47'),('2026-07-07 10:33:23'),('2026-07-07 10:33:28'),('2026-07-07 19:13:37'),('2026-07-07 21:35:40'),('2026-07-08 09:04:38'),('2026-07-08 09:06:15'),('2026-07-08 09:07:15'),('2026-07-08 12:12:14'),('2026-07-13 18:54:33'),('2026-07-13 20:13:23'),('2026-07-14 09:08:00'),('2026-07-14 09:54:04'),('2026-07-14 09:56:03'),('2026-07-16 08:55:53'),('2026-07-16 18:22:45'),('2026-07-17 10:44:44'),('2026-07-17 10:45:15'),('2026-07-17 10:45:46'),('2026-07-17 18:21:15'),('2026-07-18 09:33:35'),('2026-07-18 17:20:10'),('2026-07-20 09:02:17'),('2026-07-21 20:22:43'),('2026-07-23 09:00:40'),('2026-07-23 09:02:17'),('2026-07-23 20:20:30'),('2026-07-24 18:33:24'),('2026-07-27 20:13:16'),('2026-07-27 20:14:29'),('2026-07-28 17:35:12'),('2026-07-29 09:13:33'),('2026-07-29 20:22:11'),('2026-08-01 09:31:54'),('2026-08-01 17:25:54'),('2026-08-03 18:09:18'),('2026-08-03 19:30:57'),('2026-08-04 18:20:17'),('2026-08-05 08:55:31'),('2026-08-06 17:05:26'),('2026-08-06 17:07:36'),('2026-08-06 18:20:41'),('2026-08-06 18:22:40'),('2026-08-07 08:41:30'),('2026-08-07 19:25:48'),('2026-08-08 17:09:34'),('2026-08-08 17:13:09'),('2026-08-10 08:46:29'),('2026-08-10 18:06:39'),('2026-08-11 09:07:46'),('2026-08-11 09:08:45'),('2026-08-11 09:25:59'),('2026-08-11 17:33:04'),('2026-08-11 17:40:48'),('2026-08-12 08:44:50'),('2026-08-12 18:43:50'),('2026-08-12 19:21:19'),('2026-08-13 09:12:54'),('2026-08-13 09:23:03'),('2026-08-13 09:31:23'),('2026-08-13 17:04:50'),('2026-08-13 18:11:41'),('2026-08-13 19:50:53'),('2026-08-14 08:44:33'),('2026-08-14 08:45:47'),('2026-08-14 17:15:32'),('2026-08-18 17:27:07'),('2026-08-18 17:29:17'),('2026-08-19 08:55:10')) AS x(v)),
v AS (SELECT CAST(CONVERT(varchar(10),FALTAFW,120)+' '+HALTAFW AS datetime) ts FROM ZooLogic.COMPROBANTEV WHERE ANULADO=0 AND FALTAFW>='2026-06-25')
SELECT k.ts AS contacto_ipad,
 (SELECT COUNT(*) FROM v WHERE ABS(DATEDIFF(minute,v.ts,k.ts))<=10) AS ventas_10min,
 (SELECT COUNT(*) FROM v WHERE ABS(DATEDIFF(minute,v.ts,k.ts))<=30) AS ventas_30min,
 ca.dif_min
FROM k CROSS APPLY (SELECT TOP 1 DATEDIFF(minute,v.ts,k.ts) AS dif_min FROM v ORDER BY ABS(DATEDIFF(minute,v.ts,k.ts))) ca
ORDER BY k.ts